#include <stdio.h>
#include <math.h>

double entropy(int pos, int neg) {
    int total = pos + neg;
    if (total == 0) return 0.0;
    double p_pos = (double)pos/total;
    double p_neg = (double)neg/total;
    double h = 0.0;
    if (p_pos > 0) h -= p_pos * log2(p_pos);
    if (p_neg > 0) h -= p_neg * log2(p_neg);
    return h;
}

int main(){
    double H_parent = entropy(3,2);
    double H_sunny = entropy(2,1);
    double H_rain  = entropy(1,1);
    double IG = H_parent - (3.0/5.0)*H_sunny - (2.0/5.0)*H_rain;
    printf("%.3f\n", H_parent);
    printf("%.3f\n", IG);
    return 0;
}
